import React, { useState, useMemo, memo } from 'react';
import {
  Box,
  Typography,
  Select,
  MenuItem,
  FormControl,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
} from 'recharts';
import { getYearOptions, getCurrentYear } from '../../utils/yearOptions';
import ChartTooltip from './ChartTooltip';




const AreaGraph = ({
  title = 'Chart',
  data = [],
  onYearChange,
  selectedYear: selectedYearProp,
  lineColor = '#4CC66E',
  gradientFrom = 'rgba(76,198,110,0.30)',
  gradientTo = 'rgba(76,198,110,0.00)',
  prefix = '',
  suffix = '',
  yAxisFormatter,
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const yearOptions = useMemo(() => getYearOptions(10), []);
  const [internalYear, setInternalYear] = useState(getCurrentYear());
  const selectedYear = selectedYearProp ?? internalYear;

  const handleYearChange = (e) => {
    const yr = e.target.value;
    setInternalYear(yr);
    if (onYearChange) onYearChange(yr);
  };

 
  const gradientId = useMemo(
    () => `areaGrad_${title.replace(/\s+/g, '_').toLowerCase()}`,
    [title]
  );

  
  const defaultYFormatter = (val) => {
    if (val >= 1_000_000) return `${prefix}${(val / 1_000_000).toFixed(1)}M`;
    if (val >= 1_000)     return `${prefix}${(val / 1_000).toFixed(0)}k`;
    return `${prefix}${val}`;
  };
  const yFmt = yAxisFormatter || defaultYFormatter;

  // Every area chart here is a month-by-month series for the selected year.
  // The backend only returns months that actually have data, which makes the
  // chart render as a tiny segment (e.g. just "Jun"). Expand the series to the
  // full Jan–Dec calendar so the x-axis always shows all 12 months and the
  // line/area spans the whole year. Missing months fill in as 0.
  const MONTH_LABELS = useMemo(
    () => ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
    []
  );
  const chartData = useMemo(() => {
    const rows = Array.isArray(data) ? data : [];
    // No data yet: still draw the full year so the axis is complete.
    if (!rows.length) return MONTH_LABELS.map((m) => ({ month: m, value: 0 }));
    // Only expand to a full year for monthly series (guards non-monthly data).
    const isMonthly = rows.every((r) => MONTH_LABELS.includes(r?.month));
    if (!isMonthly) return rows;
    const byMonth = new Map(rows.map((r) => [r.month, r]));
    return MONTH_LABELS.map((m) => byMonth.get(m) || { month: m, value: 0 });
  }, [data, MONTH_LABELS]);

  return (
    <Box
      sx={{
        flex: { xs: 'none', sm: '1 1 0' },
        width: { xs: '100%', sm: 'auto' },
        minWidth: 0,
       
        background: '#001e08ff',
        backdropFilter: 'blur(12px)',
        border: '1px solid rgba(255, 255, 255, 0.08)',
        borderRadius: '24px',
        p: { xs: '12px 8px', sm: '24px 20px', md: '28px 24px' },
        display: 'flex',
        flexDirection: 'column',
        gap: { xs: '14px', md: '20px' },
        position: 'relative',
        overflow: 'hidden',
        transition: 'all 0.3s ease',
        '&:hover': {
          borderColor: 'rgba(76, 198, 110, 0.3)',
        },
       
        '&::before': {
          content: '""',
          position: 'absolute',
          top: '-15%',
          left: '-15%',
          width: '40%',
          height: '40%',
          background: `radial-gradient(circle, ${lineColor}10 0%, transparent 70%)`,
          pointerEvents: 'none',
        },
      }}
    >
      
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
          flexWrap: 'wrap',
          position: 'relative',
          zIndex: 1,
        }}
      >
        <Typography
          sx={{
            fontSize: { xs: '0.9rem', sm: '1.05rem', md: '1.15rem' },
            fontWeight: 700,
            color: '#FFFFFF',
            fontFamily: "'Montserrat', sans-serif",
            letterSpacing: '-0.02em',
          }}
        >
          {title}
        </Typography>

        
        {onYearChange && (
        <FormControl size="small" sx={{ minWidth: 100 }}>
          <Select
            value={selectedYear}
            onChange={handleYearChange}
            variant="outlined"
            MenuProps={{
              PaperProps: {
                sx: {
                  bgcolor: 'rgba(28, 28, 28, 0.95)',
                  backdropFilter: 'blur(10px)',
                  border: '1px solid rgba(255,255,255,0.1)',
                  borderRadius: '14px',
                  mt: '6px',
                  boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
                  '& .MuiMenuItem-root': {
                    fontSize: '0.8rem',
                    fontFamily: "'Montserrat', sans-serif",
                    color: 'rgba(255,255,255,0.7)',
                    borderRadius: '8px',
                    mx: '6px',
                    my: '2px',
                    '&:hover': { bgcolor: 'rgba(255,255,255,0.05)', color: '#fff' },
                    '&.Mui-selected': {
                      bgcolor: `${lineColor}20`,
                      color: lineColor,
                      fontWeight: 700,
                      '&:hover': { bgcolor: `${lineColor}30` },
                    },
                  },
                },
              },
            }}
            sx={{
              height: '36px',
              bgcolor: 'rgba(255,255,255,0.05)',
              borderRadius: '12px',
              border: '1px solid rgba(255,255,255,0.08)',
              color: 'rgba(255,255,255,0.8)',
              fontFamily: "'Montserrat', sans-serif",
              fontSize: '0.8rem',
              fontWeight: 600,
              '& .MuiOutlinedInput-notchedOutline': { border: 'none' },
              '&:hover': { bgcolor: 'rgba(255,255,255,0.08)' },
              '&.Mui-focused': { borderColor: lineColor },
              '& .MuiSelect-icon': { color: 'rgba(255,255,255,0.5)' },
            }}
          >
            {yearOptions.map((opt) => (
              <MenuItem key={opt.value} value={opt.value}>
                {opt.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        )}
      </Box>

      
      <Box sx={{ width: '100%', height: { xs: 260, sm: 260, md: 280 }, position: 'relative', zIndex: 1, mx: { xs: -1, sm: 0 } }}>
        <ResponsiveContainer width="100%" height="100%">
            <AreaChart
            data={chartData}
            margin={{
              top: 10,
              right: isMobile ? 15 : 10,
              left: isMobile ? 15 : -20,
              bottom: isMobile ? 55 : 10,
            }}
          >
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%"  stopColor={lineColor} stopOpacity={0.4} />
                <stop offset="95%" stopColor={lineColor} stopOpacity={0} />
              </linearGradient>
            </defs>

            <CartesianGrid
              strokeDasharray="0"
              stroke="rgba(255,255,255,0.03)"
              vertical={false}
            />

            <XAxis
              dataKey="month"
              interval={0}
              angle={isMobile ? -45 : 0}
              textAnchor={isMobile ? 'end' : 'middle'}
              height={isMobile ? 60 : 30}
              padding={{ left: 15, right: 15 }}
              tick={{
                fill: 'rgba(255,255,255,0.35)',
                fontSize: isMobile ? 10 : 12,
                fontFamily: "'Montserrat', sans-serif",
                fontWeight: 500,
              }}
              tickLine={false}
              axisLine={false}
              dy={isMobile ? 5 : 15}
              dx={isMobile ? -4 : 0}
            />

            {!isMobile && (
              <YAxis
                tickFormatter={yFmt}
                tick={{
                  fill: 'rgba(255,255,255,0.35)',
                  fontSize: 12,
                  fontFamily: "'Montserrat', sans-serif",
                  fontWeight: 500,
                }}
                tickLine={false}
                axisLine={false}
                width={60}
              />
            )}

            <Tooltip
              content={
                <ChartTooltip
                  accentColor={lineColor}
                  prefix={prefix}
                  suffix={suffix}
                />
              }
              cursor={{ stroke: 'rgba(255,255,255,0.1)', strokeWidth: 2 }}
            />

            <Area
              type="monotone"
              dataKey="value"
              stroke={lineColor}
              strokeWidth={4}
              fill={`url(#${gradientId})`}
              dot={false}
              activeDot={{
                r: 6,
                fill: lineColor,
                stroke: 'rgba(20,20,20,1)',
                strokeWidth: 3,
                boxShadow: `0 0 15px ${lineColor}`,
              }}
              animationDuration={2000}
              animationEasing="ease-in-out"
            />
          </AreaChart>
        </ResponsiveContainer>
      </Box>
    </Box>
  );
};

export default memo(AreaGraph);
